32 /// The reason a failed file the summary names gets when the summary's capped
33 /// list kept none for it and it was never seen live.
34 pub const NO_REASON_REPORTED: &str = "failed (the transfer's report kept no reason)";
35 
36 /// How long closing a log waits for its audit lane to drain.
37 const RELAY_DRAIN_LIMIT: Duration = Duration::from_secs(30);
38 
39 /// Where a machine keeps its logs, and whose they are.
40 #[derive(Clone, Debug)]
41 pub struct LogPlace {
42     pub dir: PathBuf,
43     /// This machine's ID ([`crate::job_log::machine_id`]).
44     pub participant: String,
45     /// Prune to the newest this many finished logs.
46     pub keep: usize,
47     /// Woken whenever a log here finishes (the daemon's `GetJobLog`
48     /// `wait_finished`).
49     pub finished: Option<Arc<tokio::sync::Notify>>,
50 }
51 
52 impl LogPlace {
53     /// Start the log of run `run_id`'s session `attempt` in `role`. `None`,
54     /// with a warning, only when the ID cannot name a log; a log never stops
55     /// a run.
56     pub fn start(&self, run_id: &str, attempt: u32, role: Role, run: RunInfo) -> Option<LogWriter> {
57         match LogKey::new(run_id, self.participant.clone(), role, attempt) {
58             Ok(key) => Some(LogWriter::start(&self.dir, key, run, self.keep)),
59             Err(error) => {
60                 log::warn!("run {run_id}: not logged: {error:#}");
61                 None
62             }
63         }
64     }
65 }
66 
67 /// A run's closing account, whatever route it took.
68 #[derive(Clone, Debug, Default, PartialEq, Eq)]
69 pub struct RunTotals {
70     pub files_copied: u64,
71     pub files_deleted: u64,
72     pub files_failed: u64,
73     pub bytes_copied: u64,
74     pub files_resumed: u64,
75     /// Whether the payload rode the in-stream carrier; `None` where the
76     /// question does not arise (a local run).
77     pub in_stream_carrier: Option<bool>,
78     /// The failed files by name; exact unless `failed_paths_truncated`.
79     pub failed_paths: Vec<String>,
80     /// cr-ecm34-5: the exact bytes of each of `failed_paths` whose name is
81     /// not text, at its place in that list, and nothing at the place of one
82     /// that is — one entry for every path, so a failure past the summary's
83     /// reason cap is still named by its own bytes.
84     pub failed_paths_raw: Vec<Vec<u8>>,
85     pub failed_paths_truncated: bool,
86     /// As many failed files as the report kept, each with its reason and
87     /// — when its name is not its text — its own bytes (review
88     /// cr-jl3afix1-1).
89     pub failures: Vec<FileFailure>,
90     /// The failed files whose write left this run's own incomplete copy at
91     /// the destination, and whether that list is whole (review cr-jl4-1:
92     /// an `--ignore-existing` retry must not skip them as existing).
93     pub left_in_place: Vec<String>,
94     pub left_in_place_truncated: bool,
95     /// The same for names that are not UTF-8, by their exact bytes (review
96     /// cr-jl4fix2-1).
97     pub left_in_place_raw: Vec<Vec<u8>>,
98 }
99 
100 impl RunTotals {
101     /// Add `other`'s account to this one: the parts of one run.
102     pub fn merge(&mut self, other: RunTotals) {
103         self.files_copied += other.files_copied;
104         self.files_deleted += other.files_deleted;
105         self.files_failed += other.files_failed;
106         self.bytes_copied += other.bytes_copied;
107         self.files_resumed += other.files_resumed;
108         self.in_stream_carrier = match (self.in_stream_carrier, other.in_stream_carrier) {
109             (Some(a), Some(b)) => Some(a || b),
110             (a, b) => a.or(b),
111         };
112         let mut other_raw = other.failed_paths_raw;
113         other_raw.resize(other.failed_paths.len(), Vec::new());
114         self.failed_paths_raw
115             .resize(self.failed_paths.len(), Vec::new());
116         self.failed_paths.extend(other.failed_paths);
117         self.failed_paths_raw.extend(other_raw);
118         self.failed_paths_truncated |= other.failed_paths_truncated;
119         self.failures.extend(other.failures);
120         self.left_in_place.extend(other.left_in_place);
121         self.left_in_place_truncated |= other.left_in_place_truncated;
122         self.left_in_place_raw.extend(other.left_in_place_raw);
123     }
124 }
125 
126 /// A summary's `failed_paths_raw` at their places: one entry for every
127 /// path (the wire sends either that, or none when no name needs bytes).
128 pub fn raw_at_their_places(paths: &[String], raw: &[Vec<u8>]) -> Vec<Vec<u8>> {
129     if raw.len() == paths.len() {
130         raw.to_vec()
131     } else {
132         vec![Vec::new(); paths.len()]
133     }
134 }
135 
136 impl From<&TransferSummary> for RunTotals {
137     fn from(summary: &TransferSummary) -> Self {
138         Self {
139             files_copied: summary.files_transferred,
140             files_deleted: summary.entries_deleted,
141             files_failed: summary.files_failed,
142             bytes_copied: summary.bytes_transferred,
143             files_resumed: summary.files_resumed,
144             in_stream_carrier: Some(summary.in_stream_carrier_used),
145             failed_paths: summary.failed_paths.clone(),
146             failed_paths_raw: raw_at_their_places(&summary.failed_paths, &summary.failed_paths_raw),
147             failed_paths_truncated: summary.failed_paths_truncated,
148             failures: summary
149                 .failures
150                 .iter()
151                 .map(FileFailure::from_wire)
152                 .collect(),
153             left_in_place: summary.left_in_place.clone(),
154             left_in_place_truncated: summary.left_in_place_truncated,
155             left_in_place_raw: summary.left_in_place_raw.clone(),
156         }
157     }
158 }
