430 /// Every file a run failed, by its text and bytes: its record's, completed
431 /// from this machine's log of the run when the record's list was cut
432 /// short — with, from the log's whole reasons, the texts of those whose
433 /// failed write left the run's own incomplete copy. An error when they are
434 /// still not all known — a retry would leave the rest.
435 fn failed_identities(
436     config_dir: &Path,
437     record: &RunRecord,
438 ) -> Result<(HashSet<(String, Option<String>)>, LoggedLeftovers)> {
439     // cr-ecm34-7: every recorded failure is a file, whatever its name; the
440     // failures no retry pass was given are not in the list, and the count
441     // says the list is short.
442     let mut known: HashSet<(String, Option<String>)> = record
443         .failures
444         .iter()
445         .map(|failure| (failure.path.clone(), failure.raw.clone()))
446         .collect();
447     let short = |known: &HashSet<(String, Option<String>)>| {
448         record.failures_truncated || (known.len() as u64) < record.files_failed
449     };
450     let mut logged = LoggedLeftovers::default();
451     // Review cr-jl4fix4-1: a record from before its lists kept identities,
452     // naming a raw-named failure whose text is in its text list, needs the
453     // log whether or not its failure list is whole.
454     let ambiguous_legacy = !record.left_in_place_exact
455         && record.failures.iter().any(|failure| {
456             failure.raw.is_some()
457                 && record
458                     .left_in_place
459                     .iter()
460                     .any(|left| left == &failure.path)
461         });
