463         // Review cr-jl4-3: the run's terminal state, read from its log in
464         // order — a file that failed, and was not landed by a later pass —
465         // not every failure the run ever met.
466         let logs = config_dir.join("jobs").join("logs");
467         let found = job_log::logs_for_run(&logs, &record.run_id, None).unwrap_or_default();
468         logged.complete = !found.is_empty();
469         // Reviews cr-jl4fix5-1, cr-jl4fix6-1: a run's sessions on one
470         // machine in one role are one stream, folded in attempt order (as
471         // `logs_for_run` lists them) — a later attempt's copy clears an
472         // earlier one's leftover, a later failure without one does not
473         // revive it; one stream's events never clear another's evidence;
474         // what each stream holds at its end is united.
475         type Identities = HashSet<(String, Option<String>)>;
476         let mut streams: HashMap<(String, Role), (Identities, Identities)> = HashMap::new();
477         for log in found {
478             let Ok(lines) = job_log::open_log(&log.path) else {
479                 logged.complete = false;
480                 continue;
481             };
482             logged.read = true;
483             let mut whole = log.finished;
484             let mut ended = false;
485             let (left, still_failed) = streams
486                 .entry((log.key.participant().to_string(), log.key.role()))
487                 .or_default();
488             for line in lines {
489                 let Ok(LogLine::Event(event)) = line else {
490                     whole = false;
491                     continue;
492                 };
493                 match event.body {
494                     job_log::EventBody::FileFailed {
495                         path,
496                         raw,
497                         left_in_place,
498                         ..
499                     } => {
500                         match left_in_place {
501                             Some(true) => {
502                                 left.insert((path.clone(), raw.clone()));
503                             }
504                             Some(false) => {}
505                             None => logged.left_unknown = true,
506                         }
507                         still_failed.insert((path, raw));
508                     }
509                     // A copy landed the file; a send only sent it — whether it
510                     // landed is the destination's to say, so a send clears no
511                     // leftover.
512                     job_log::EventBody::FileCopied { path, raw, .. } => {
513                         let identity = (path, raw);
514                         left.remove(&identity);
515                         still_failed.remove(&identity);
516                     }
517                     job_log::EventBody::FileSent { path, raw } => {
518                         still_failed.remove(&(path, raw));
519                     }
520                     job_log::EventBody::RunEnd { .. } => ended = true,
521                     job_log::EventBody::LogIncomplete { .. } => whole = false,
522                     _ => {}
523                 }
524             }
525             logged.complete &= whole && ended;
526         }
527         for (left, still_failed) in streams.into_values() {
528             logged.left.extend(left);
529             known.extend(still_failed);
530         }
531         if (known.len() as u64) < record.files_failed {
532             eyre::bail!(
533                 "job {} names only {} of the {} files it failed, so a retry would leave the \
