546 /// A retry's names (reviews cr-jl4-2, cr-jl4fix1-2): each failed file by
547 /// its text, or — a name that is not UTF-8, whose text names no file — by
548 /// its exact bytes, kept as bytes whatever this host is, so they reach a
549 /// remote source as they are; only the host that enumerates them turns them
550 /// into its paths. Bytes the record cannot give back fall to the text.
551 fn retry_names<'a>(
552     failed: impl Iterator<Item = &'a (String, Option<String>)>,
553 ) -> (HashSet<PathBuf>, HashSet<Vec<u8>>) {
554     let mut names = HashSet::new();
555     let mut raw_names = HashSet::new();
556     for (path, raw) in failed {
557         match raw.as_deref().and_then(blit_core::raw_name::unescape_raw) {
558             Some(bytes) => {
559                 raw_names.insert(bytes);
560             }
561             None => {
562                 names.insert(PathBuf::from(path));
563             }
564         }
565     }
566     (names, raw_names)
567 }
