661     let record = &mut recorded.record;
662     record.ended_ms = Some(now_ms());
663     record.state = match ending {
664         Some(Ending::Detached { daemon, job_id }) => RunState::Waiting { daemon, job_id },
665         Some(Ending::Interrupted(_)) => RunState::Interrupted,
666         None => RunState::Finished,
667     };
668     record.outcome = match record.state {
669         RunState::Waiting { .. } => None,
670         _ => Some(outcome),
671     };
672     record.detail = detail;
673     record.source_removed = source_removed;
674     record.destination_nested = destination_nested;
675     if let Some(totals) = totals {
676         record.files_copied = totals.files_copied;
677         record.files_deleted = totals.files_deleted;
678         record.files_failed = totals.files_failed;
679         record.bytes_copied = totals.bytes_copied;
