684             .failures
685             .iter()
686             .map(|failure| Failure {
687                 path: failure.relative_path.clone(),
688                 reason: failure.reason.clone(),
689                 raw: failure
690                     .raw_relative_path
691                     .as_deref()
692                     .map(blit_core::raw_name::escape_raw)
693                     .or_else(|| raws.get(&failure.relative_path).cloned()),
694             })
695             .collect();
696         for path in &totals.failed_paths {
697             if !failures.iter().any(|failure| &failure.path == path) {
698                 failures.push(Failure {
699                     path: path.clone(),
700                     reason: String::new(),
701                     raw: raws.get(path).cloned(),
702                 });
