178 /// One file the destination could not materialize, named for the
179 /// end-of-operation summary. `relative_path` is the manifest-relative
180 /// wire path, empty for the single-file destination convention (the
181 /// destination root IS the file — same rule as `FileHeader`).
182 #[derive(Debug, Default, Clone, PartialEq, Eq)]
183 pub struct FileFailure {
184     pub relative_path: String,
185     pub reason: String,
186     /// The failed entry's exact name bytes when they are not the text's —
187     /// set where the failure is made, so a name that collides with another
188     /// in its lossy text still names its own file (review cr-jl3afix1-1).
189     pub raw_relative_path: Option<Vec<u8>>,
190     /// D-2026-11-24-1: the failure left this run's own incomplete copy at
191     /// the destination — set where that is known, never read from
192     /// `reason`, which is for people.
193     pub left_in_place: bool,
194 }
195 
196 impl FileFailure {
197     /// Wire form of one contained failure (contract v6), per-entry
198     /// bounded (cr-pfc4-2).
199     ///
200     /// The per-string bounds live HERE, not at the call site, so no
201     /// producer of a wire entry can put an unbounded string on the
202     /// closing summary frame: `reason` keeps its head up to
203     /// [`MAX_FAILURE_REASON_BYTES`], `relative_path` keeps its tail up
204     /// to [`MAX_FAILURE_PATH_BYTES`]. Both cut on a char boundary and
205     /// mark the cut; anything already inside its bound is copied
206     /// byte-identically. The in-memory record keeps its full strings —
207     /// the bound is the wire's, and the whole reason is already in the
208     /// log `record_failure` wrote.
209     pub fn to_wire(&self) -> crate::generated::FileFailure {
210         crate::generated::FileFailure {
211             relative_path: bounded_tail(&self.relative_path, MAX_FAILURE_PATH_BYTES),
212             reason: bounded_head(&self.reason, MAX_FAILURE_REASON_BYTES),
213             // A cut name is no identity: bytes past the bound are dropped
214             // whole, and the text stands alone.
215             raw_relative_path: self
216                 .raw_relative_path
217                 .clone()
218                 .filter(|raw| raw.len() <= MAX_FAILURE_PATH_BYTES)
219                 .unwrap_or_default(),
220             left_in_place: self.left_in_place,
221         }
222     }
223 
224     /// The inverse, for a caller reading a peer's summary back into the
225     /// in-memory report (the local summary surface, pfc-5's renderer).
226     pub fn from_wire(wire: &crate::generated::FileFailure) -> Self {
227         Self {
228             relative_path: wire.relative_path.clone(),
229             reason: wire.reason.clone(),
230             raw_relative_path: (!wire.raw_relative_path.is_empty())
231                 .then(|| wire.raw_relative_path.clone()),
232             // cr-ecm34-5: as the wire carries it (contract 30).
233             left_in_place: wire.left_in_place,
234         }
235     }
236 }
