502 /// The pass loop, shared by every route. `run` executes one retry pass
503 /// with the prepared arguments (the retry-only set and the pass label
504 /// already threaded in) and returns that pass's result.
505 ///
506 /// 2026-10-07 defect (b): Ctrl-C during the retry wait or a retry pass
507 /// stops the retries instead of killing the process, so the route still
508 /// prints the report of the pass that already ran — its deletions
509 /// included — and exits [`INTERRUPTED_EXIT`]. Once the handler has been
510 /// installed, a later Ctrl-C exits at once, as the default did.
511 pub(crate) async fn run_retry_passes<F, Fut>(
512     args: &TransferArgs,
513     main: PassFailures,
514     run: F,
515 ) -> Result<RetryOutcome>
516 where
517     F: FnMut(TransferArgs) -> Fut,
518     Fut: Future<Output = Result<PassResult>>,
519 {
520     let armed = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
521     let interrupt = {
522         let armed = std::sync::Arc::clone(&armed);
523         async move {
524             armed.store(true, std::sync::atomic::Ordering::Relaxed);
525             if tokio::signal::ctrl_c().await.is_err() {
526                 // No handler could be installed: never interrupt.
527                 std::future::pending::<()>().await;
528             }
529         }
530     };
531     let outcome = run_retry_passes_until(args, main, run, interrupt).await;
532     if armed.load(std::sync::atomic::Ordering::Relaxed) {
533         tokio::spawn(async {
534             if tokio::signal::ctrl_c().await.is_ok() {
535                 std::process::exit(i32::from(INTERRUPTED_EXIT));
536             }
537         });
538     }
539     outcome
540 }
