2024 /// The [`RecordWriter`] of [`FsTransferSink`] (contract v7). Owns the
2025 /// in-place target handle for the record's duration and the guard that
2026 /// removes the partial target unless the record is committed.
2027 struct FsRecordWriter<'a> {
2028     sink: &'a FsTransferSink,
2029     header: FileHeader,
2030     dst: PathBuf,
2031     mode: FsRecordMode,
2032     written: u64,
2033     /// Bytes reported to the live byte counter for this record; given
2034     /// back on abort (pfc-4 byte-lane reconciliation).
2035     reported: u64,
2036     /// Cleared by `commit`/`abort`; while set, `Drop` removes the
2037     /// partial target a real record created (cancellation path — the
2038     /// receive task is aborted by dropping its future,
2039     /// `abort_on_drop.rs`, which would otherwise leave a truncated file
2040     /// that looks finished).
2041     guard_armed: bool,
2042     /// cr-ecm18-1: which file this record made, whatever the run: its
2043     /// target is settled only while that file stands at the name, with or
2044     /// without the handle — and (cr-ecm16-2, cr-ecm19-2) it lands only
2045     /// while that file is what the name holds.
2046     own: Option<(u64, u64)>,
2047 }
