2050     fn new(sink: &'a FsTransferSink, header: FileHeader, dst: PathBuf, mode: FsRecordMode) -> Self {
2051         let guard_armed = matches!(mode, FsRecordMode::Real { .. });
2052         Self {
2053             sink,
2054             header,
