        use crate::job_log::{Event, EventBody, LogLine};
        let mut read = LogRead::default();
        for (seq, body) in [
            EventBody::FileFailed { path:"a".into(), reason:"old".into(), raw:None, left_in_place:None },
            EventBody::FileCopied { path:"a".into(), raw:None, bytes:None },
            EventBody::FileFailed { path:"b".into(), reason:"known".into(), raw:None, left_in_place:Some(true) }
        ].into_iter().enumerate() {
            read.read_line(LogLine::Event(Event {ts_ms:1, seq:seq as u64, body}));
        }
        assert_eq!(read.failures.len(),1);
        assert_eq!(read.left_in_place,vec![("b".to_string(), None)]);
        let ended=read.ended_record(&RunRecord::starting(RUN, &spec()), false);
